SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, CASE WHEN humidity >= 71 THEN 'LARGE' ELSE 'SMALL' END AS humidity_tier, COUNT_IF(device_code = 'DV-02') AS dv_02_events, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min FROM device_readings GROUP BY DATE_TRUNC('DAY', reading_ts), CASE WHEN humidity >= 71 THEN 'LARGE' ELSE 'SMALL' END ORDER BY humidity_tier DESC NULLS LAST;
